		} else {
			text += document.title + ' - ';
		}
		if (target.text() == "" && megaMenuText == "") {
			text += "N/A";
		} else if (target.text().length && megaMenuText.length) {
			if (megaMenuText == target.text()) {
				text += megaMenuText;
			} else {
				text += megaMenuText + " - " + subTitleText + " - " + target.text();
			}
		} else if (target.text() == "") {
